{{
  (function() {
    const machines = sel_loc_machine.selectedOptionValues || [];
    if (machines.length === 0) {
      return "ℹ️ **Sélectionnez au moins une machine** pour afficher les plannings.";
    }

    const resas = Get_Calendar_Events_Machine.data || [];

    if (resas.length === 0) {
      return "✅ **Disponibilité validée** (aucune réservation à venir pour la sélection).";
    }

    let planning = "📅 **Réservations à venir pour ces matériels :**\n";
    resas.forEach(r => {
      const date = moment(r.Date_Location).format("DD/MM/YYYY");
      planning += `• **${date}** [${r.Type_Duree}] — ${r.Machine_Louee} (${r.Client_Affichage})\n`;
    });

    return planning;
  })()
}}
